insert into public.testimonials (company, quote, rating, person_name, sort_order, published) values
  ('National Referral Hospital', 'They filmed our wards with real respect for patients and staff. The documentary is now part of our induction for every new nurse.', 5, '', 1, true),
  ('Tanzania Health Summit', 'Three days, four halls, one live stream that never dropped. Delegates had their photos before the closing dinner.', 5, '', 2, true),
  ('Bank Foundation', 'The scholarship film made our board cry and our applications double. Calm crew, sharp edit, delivered early.', 5, '', 3, true),
  ('University of Health Sciences', 'Graduates found their photos with a selfie. Parents still send us thank-you messages about that gallery.', 5, '', 4, true);
